// Generated by AI
using System;
using UnityEngine;

namespace GuardiansOfTheWetland.Gameplay
{
    [RequireComponent(typeof(Rigidbody2D), typeof(BoxCollider2D))]
    public sealed class MovingPlatform : MonoBehaviour
    {
        private Rigidbody2D body;
        private Vector2 start;
        private Vector2 end;
        private Vector2 target;
        private float speed;
        private Action onDirectionChanged;
        private bool configured;

        public void Configure(
            Vector2 endOffset,
            float unitsPerSecond,
            Action onDirectionChanged = null)
        {
            body = GetComponent<Rigidbody2D>();
            body.bodyType = RigidbodyType2D.Kinematic;
            body.interpolation = RigidbodyInterpolation2D.Interpolate;
            GetComponent<BoxCollider2D>().isTrigger = false;

            start = body.position;
            end = start + endOffset;
            target = end;
            speed = unitsPerSecond;
            this.onDirectionChanged = onDirectionChanged;
            configured = endOffset.sqrMagnitude > 0f && speed > 0f;
        }

        private void FixedUpdate()
        {
            if (!configured)
                return;

            if ((body.position - target).sqrMagnitude <= 0.000001f)
            {
                target = target == end ? start : end;
                onDirectionChanged?.Invoke();
            }

            Vector2 next = Vector2.MoveTowards(
                body.position, target, speed * Time.fixedDeltaTime);

            body.MovePosition(next);
        }
    }
}
